                    const card = e.target.closest('.card');
                    if (!card) return;
                    const name = card.dataset.name;

                    if (this.selectedCandidate === name) {
                        this.selectedCandidate = null;
                        card.classList.remove('selected');
                    } else {
                        if (this.selectedCandidate) {
                            const previousCard = this.elements.candidatesContainer.querySelector(`.card[data-name="${this.selectedCandidate}"]`);
                            if(previousCard) previousCard.classList.remove('selected');
                        }
                        this.selectedCandidate = name;
                        card.classList.add('selected');
                    }
                    this.updateConfirmButton();
                });

